        ["Удаляет DXCache, GLCache, AMD DxCache и D3DSCache. Заблокированные файлы пропускаются."] = "Deletes DXCache, GLCache, AMD DxCache and D3DSCache. Locked files are skipped.",
        ["Удаляет временные файлы, которые могут замедлить систему"] = "Deletes temporary files that may slow down the system",
