        ["Ограничьте максимальную частоту процессора, чтобы снизить тепловую нагрузку и энергопотребление. Понижение до 10% экономит потребление энергии (полезно для ноутбуков), 100% даёт полный приток мощности."] = "Limit the maximum CPU frequency to reduce heat and power consumption. Lowering to 10% saves energy (useful for laptops), 100% gives full power.",
