        ["Диагностика в один клик"] = "One-click diagnostics",
        ["Диагностика завершена. Windows проверила образ системы, диск, системные файлы и загрузчик и автоматически исправила найденные проблемы. Обычно больше ничего делать не нужно; если система попросит — перезагрузите ПК."] = "Diagnostics completed. Windows checked the system image, the disk, system files and the bootloader and automatically fixed the issues it found. Usually nothing else is needed; restart your PC if the system asks you to.",
