        ["Политика AllowTelemetry (HKLM)"] = "AllowTelemetry-Richtlinie (HKLM)",
        ["Полностью отключает антивирус: политики, службы, а также удаляет приложение «Безопасность Windows» и службы статуса. Включение обратно пытается всё восстановить."] = "Deaktiviert den Antivirus vollständig: Richtlinien, Dienste und entfernt die App „Windows-Sicherheit“ sowie Statusdienste. Das erneute Aktivieren versucht, alles wiederherzustellen.",
        ["Полностью отключает фильтрацию сетевого трафика для всех профилей."] = "Deaktiviert die Netzwerkverkehrsfilterung für alle Profile vollständig.",
        ["Пользователь"] = "Benutzer",
        ["Помогает при микрофризах после обновлений"] = "Hilft bei Mikrorucklern nach Updates",
        ["Помогает стабилизировать пинг и устранить микро-лаги в онлайн-играх."] = "Hilft, den Ping zu stabilisieren und Mikrolags in Online-Spielen zu beheben.",
        ["Популярные компоненты"] = "Beliebte Features",
        ["Популярные приложения — одним кликом через winget."] = "Beliebte Apps — Installation mit einem Klick über winget.",
        ["При запуске Проводника открывает «Этот компьютер» вместо «Главной»."] = "Öffnet „Dieser PC“ statt „Start“ beim Explorer-Start.",
        ["Применить"] = "Übernehmen",
