        ["Программы при запуске Windows"] = "Programme beim Windows-Start",
        ["Программы, запускающиеся вместе с Windows. Включайте и отключайте их одним переключателем, не редактируя реестр вручную."] = "Programme, die mit Windows starten. Aktivieren und deaktivieren Sie sie mit einem Schalter, ohne die Registrierung manuell zu bearbeiten.",
        ["Производительность системы"] = "Systemleistung",
        ["Просмотр запущенных процессов, сортировка по потреблению ОЗУ и завершение одним нажатием."] = "Aktive Prozesse anzeigen, nach RAM-Nutzung sortieren und mit einem Klick beenden.",
