        ["Ручная установка"] = "Manuelle Installation",
        ["Ручной ввод ID пакета"] = "Manuelle Paket-ID-Eingabe",
        ["Сбрасывает закешированные DNS-записи — помогает при проблемах с подключением к серверам игр."] = "Leert den DNS-Cache — hilft bei Verbindungsproblemen zu Spielservern.",
        ["Сбрасывает рабочие наборы всех процессов, освобождая занятую память (аналог Mem Reduct)."] = "Setzt die Arbeitssätze aller Prozesse zurück und gibt Speicher frei (wie Mem Reduct).",
        ["Сбросить"] = "Zurücksetzen",
        ["Сбросить к значениям по умолчанию"] = "Auf Standardwerte zurücksetzen",
        ["Сводные характеристики вашего устройства: система, процессор, память и комплектующие."] = "Zusammenfassung Ihres Geräts: System, Prozessor, Speicher und Komponenten.",
