        ["Скрывает логотип Windows при загрузке системы."] = "Blendet das Windows-Logo beim Booten aus.",
        ["Скрыть кнопки «Просмотр задач» и «Виджеты»"] = "Schaltflächen „Aufgabenansicht“ und „Widgets“ ausblenden",
        ["Служба DiagTrack"] = "DiagTrack-Dienst",
        ["Служба WAP Push (dmwappushservice)"] = "WAP-Push-Dienst (dmwappushservice)",
        ["Смена названия процессора в диспетчере задач."] = "Prozessornamen im Task-Manager ändern.",
        ["Снижает количество рекламных предложений и рекомендаций в меню «Пуск»."] = "Reduziert Werbeangebote und Empfehlungen im Startmenü.",
        ["Снижает рекомендации в меню Пуск (Start_IrisRecommendations = 0)."] = "Reduziert Empfehlungen im Startmenü (Start_IrisRecommendations = 0).",
        ["Снижает сетевую задержку: мгновенная отправка ACK и DSCP-метка приоритета для игрового трафика."] = "Reduziert Netzwerklatenz: sofortiges ACK-Senden und DSCP-Prioritätskennzeichnung für Spielverkehr.",
        ["Снизить системную задержку"] = "Systemlatenz reduzieren",
        ["Совместимость со старыми приложениями."] = "Kompatibilität mit alten Anwendungen.",
        ["Создать точку восстановления"] = "Wiederherstellungspunkt erstellen",
        ["Сохранить и применить тему"] = "Design speichern und anwenden",
        ["Таймер выключения"] = "Herunterfahren-Timer",
        ["Телеметрия и конфиденциальность"] = "Telemetrie und Datenschutz",
        ["Тема оформления, сохранение параметров в приложении."] = "Design und Speichern der Einstellungen in der Anwendung.",
        ["Тема приложения"] = "Anwendungsdesign",
        ["Точки восстановления, сжатие системы и параметры телеметрии."] = "Wiederherstellungspunkte, Systemkomprimierung und Telemetrieeinstellungen.",
        ["Убирает антивирус, окно «Безопасность Windows» и индикацию статуса защиты."] = "Entfernt den Antivirus, das Fenster „Windows-Sicherheit“ und die Schutzstatusanzeige.",
        ["Убирает кнопку просмотра задач и виджеты с панели задач."] = "Entfernt die Schaltfläche „Aufgabenansicht“ und Widgets aus der Taskleiste.",
        ["Убирает проверку приложений и файлов из интернета (может снизить безопасность)."] = "Entfernt die Überprüfung von Apps und Dateien aus dem Internet (kann die Sicherheit verringern).",
        ["Убирает суффикс « — ярлык» у новых создаваемых ярлыков."] = "Entfernt das Suffix „ — Verknüpfung“ bei neu erstellten Verknüpfungen.",
        ["Убрать « — ярлык» в имени новых ярлыков"] = "„ — Verknüpfung“ aus neuen Verknüpfungsnamen entfernen",
        ["Убрать задержку контекстного меню"] = "Kontextmenü-Verzögerung entfernen",
        ["Удаление UWP приложений"] = "UWP-Apps entfernen",
        ["Удалить"] = "Löschen",
        ["Удалить по ID"] = "Per ID entfernen",
        ["Удаляет DXCache, GLCache, AMD DxCache и D3DSCache. Заблокированные файлы пропускаются."] = "Löscht DXCache, GLCache, AMD DxCache und D3DSCache. Gesperrte Dateien werden übersprungen.",
        ["Удаляет временные файлы, которые могут замедлить систему"] = "Löscht temporäre Dateien, die das System verlangsamen können",
        ["Удаляет закешированные миниатюры папок и файлов (thumbcache), освобождая место и устраняя битые иконки."] = "Löscht gecachte Miniaturansichten von Ordnern und Dateien (thumbcache), gibt Speicherplatz frei und behebt defekte Symbole.",
        ["Ультрапроизводительность (Ultimate Performance)"] = "Ultimate Performance",
        ["Уменьшает задержку при передаче мелких пакетов (снижает пинг)."] = "Reduziert die Latenz bei kleinen Paketen (senkt den Ping).",
        ["Уменьшает кнопки управления окном для компактности панели задач."] = "Verkleinert die Fenstersteuerungsschaltflächen für eine kompaktere Taskleiste.",
        ["Уменьшает назойливость запросов обратной связи и фоновую отправку отчётов (где применимо)."] = "Reduziert Feedback-Aufforderungen und das Hintergrund-Senden von Berichten (wo zutreffend).",
        ["Уменьшить рекламу в меню «Пуск» и на панели задач"] = "Werbung im Startmenü und in der Taskleiste reduzieren",
        ["Управление процессами"] = "Prozessverwaltung",
        ["Устанавливает высокий приоритет процессора для cs2.exe (включать при запущенной игре)."] = "Setzt hohe CPU-Priorität für cs2.exe (bei laufendem Spiel aktivieren).",
        ["Устанавливает политику AllowTelemetry = 0 в реестре HKLM — отключает телеметрию."] = "Setzt die Richtlinie AllowTelemetry = 0 in der Registrierung HKLM — deaktiviert Telemetrie.",
