        ["Работают без открытого окна."] = "Laufen ohne offenes Fenster.",
        ["Сбрасывает Winsock, TCP/IP, IPv6, DNS и ARP. Помогает, когда интернет «пропал». Требуется перезагрузка."] = "Setzt Winsock, TCP/IP, IPv6, DNS und ARP zurück. Hilft, wenn das Internet „weg“ ist. Ein Neustart ist erforderlich.",
        ["Сброс сетевого стека"] = "Netzwerk-Stack zurücksetzen",
        ["Сбросить Winsock, TCP/IP, IPv6, DNS и ARP?\n\nРекомендуется перезагрузка."] = "Winsock, TCP/IP, IPv6, DNS und ARP zurücksetzen?\n\nEin Neustart wird empfohlen.",
        ["Сбросить кэш DNS Windows? Это безопасно и не требует перезагрузки."] = "Den Windows-DNS-Cache zurücksetzen? Das ist sicher und erfordert keinen Neustart.",
        ["Сбросить рабочие наборы всех процессов текущего пользователя? Активные окна могут на мгновение «подвиснуть»."] = "Die Arbeitssätze aller Prozesse des aktuellen Benutzers zurücksetzen? Aktive Fenster können kurz einfrieren.",
        ["Сбросить стек"] = "Stack zurücksetzen",
        ["Сгруппировать по .exe"] = "Nach .exe gruppieren",
        ["Сетевой стек сброшен. Перезагрузите компьютер для полного применения."] = "Der Netzwerk-Stack wurde zurückgesetzt. Starten Sie den Computer neu, damit alles wirksam wird.",
        ["Сетевые настройки"] = "Netzwerkeinstellungen",
        ["Сетевые параметры"] = "Netzwerkparameter",
        ["Сетевые твики Windows, сброс стека, IPv6, DNS, тест задержки, пароли Wi-Fi и блокировка телеметрии."] = "Windows-Netzwerk-Tweaks, Stack-Reset, IPv6, DNS, Latenztest, WLAN-Passwörter und Telemetrie-Sperre.",
        ["Снижает задержку вывода кадра. Изменение применится после перезагрузки."] = "Reduziert die Latenz der Bildausgabe. Die Änderung wird nach einem Neustart wirksam.",
